package com.anthony6996.hardcorecompass.listener;
import com.anthony6996.hardcorecompass.config.ConfigManager;import com.anthony6996.hardcorecompass.manager.*;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.entity.PlayerDeathEvent;import org.bukkit.inventory.ItemStack;
public final class PlayerDeathListener implements Listener{private final LivesManager lives;private final CompassManager compass;private final TeleportManager teleport;private final ConfigManager config;public PlayerDeathListener(LivesManager l,CompassManager c,TeleportManager t,ConfigManager cfg){lives=l;compass=c;teleport=t;config=cfg;}@EventHandler(priority=EventPriority.HIGHEST)public void onDeath(PlayerDeathEvent e){Player p=e.getEntity();lives.initialize(p.getUniqueId());ItemStack keep=compass.findTaggedCompass(p);boolean preserve=config.preserveOnFirstDeath()&&lives.deaths(p.getUniqueId())==0&&keep!=null&&lives.markCompassPreserved(p.getUniqueId());int remaining=lives.recordDeath(p.getUniqueId());if(config.wipeInventory())e.getDrops().clear();if(preserve){e.getItemsToKeep().add(keep.clone());e.setKeepInventory(true);}e.setDroppedExp(config.clearXp()?0:e.getDroppedExp());if(config.clearEnderChest())p.getEnderChest().clear();if(config.clearXp()){p.setExp(0);p.setLevel(0);p.setTotalExperience(0);}if(config.clearBedSpawn())p.setBedSpawnLocation(null,true);e.setDeathMessage(config.getMessage(p,remaining>0?"death-one":"death-final").replace("{lives}",String.valueOf(remaining)));if(config.enableRtp())teleport.relocate(p);}}
